python - <<'PY'
import csv,re
from collections import Counter
allowed={'O','Cu','Ba','Sr','Y','Ca','La','Bi','Fe','Nb','C','Pr','As','B','Pb','Ce','Mo','V','Zn','Ni'}
pat=re.compile(r'([A-Z][a-z]?)([0-9]*\.?[0-9]*)')
rows=[]
with open('b3_supercon_data.csv',newline='') as f:
    for r in csv.DictReader(f):
        d=Counter()
        for e,n in pat.findall(r['composition']): d[e]+=float(n or 1)
        total=sum(d.values())
        frac={e:v/total for e,v in d.items()}
        if set(d)<=allowed and len(d)<=4:
            rows.append((float(r['target']),r['composition'],frac))
for t,c,f in sorted(rows,reverse=True)[:30]:
    print(f'{t:6.1f} {c:30s} '+', '.join(f'{e}={v:.6f}' for e,v in f.items()))
